from collections import defaultdict, deque

def solve(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = [False] * (n + 1)
    path_count = [-1] * (n + 1)
    cycle_detected = [False]

    def dfs(node):
        if visited[node]:
            if path_count[node] == -1:
                cycle_detected[0] = True
            return

        visited[node] = True
        path_count[node] = 0

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
            elif path_count[neighbor] == -1:
                cycle_detected[0] = True

        if not cycle_detected[0]:
            path_count[node] = 1

    dfs(1)

    if cycle_detected[0]:
        return [-1] * (n + 1)

    result = []
    for i in range(1, n + 1):
        if not visited[i]:
            result.append(0)
        elif path_count[i] == -1:
            result.append(2)
        else:
            result.append(1)

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        m = int(data[index + 1])
        index += 2
        edges = []
        for i in range(m):
            a = int(data[index])
            b = int(data[index + 1])
            edges.append((a, b))
            index += 2
        results.append(solve(n, edges))

    for result in results:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
